1	// src/learn/Markers.ts —— AI 回复中的教学标记解析
2	//
3	// AI 在教学/摸底/随堂判定时输出结构化标记（提示词约定），扩展端解析并落盘：
4	//   <lesson-advance/>                                  → 本节通过，推进到下一节
5	//   <profile-update>{"level":"beginner",...}</profile-update> → 更新学生画像
6	//   <wrong-book>{"lesson":"...","section":"...","question":"..."}</wrong-book> → 错题归档
7	// parseMarkers 返回剥离标记后的干净正文与解析结果；JSON 损坏的标记按剥离处理（不崩溃）。
8	
9	import type { StudentProfile } from './ProgressStore';
10	
11	export interface MarkerResult {
12	  clean: string;
13	  profileUpdate?: Partial<StudentProfile>;
14	  lessonAdvance: boolean;
15	  wrong?: { lesson: string; section: string; question: string };
16	  /** 随堂练习的测试输入（AI 出题时给出，运行时喂给程序 stdin；可多个测试点） */
17	  testInputs: string[];
18	  /** 每个测试点的期望输出（与 testInputs 按序对应；扩展端自动比对判定，不依赖 AI 印象） */
19	  expectedOutputs: string[];
20	  /** AI 要求自动编译运行的文件（相对路径） */
21	  runFile?: string;
22	  /** AI 设定的当前任务目标（空串 = 清除任务） */
23	  currentTask?: string;
24	}
25	
26	export function parseMarkers(raw: string): MarkerResult {
27	  let clean = raw;
28	  let profileUpdate: MarkerResult['profileUpdate'];
29	  let lessonAdvance = false;
30	  let wrong: MarkerResult['wrong'];
31	  const testInputs: string[] = [];
32	  const expectedOutputs: string[] = [];
33	  let wrong_run_file: string | undefined;
34	  let currentTask: string | undefined;
35	
36	  const prof = /<profile-update>([\s\S]*?)<\/profile-update>/.exec(clean);
37	  if (prof) {
38	    clean = clean.replace(prof[0], '');
39	    try {
40	      const obj = JSON.parse(prof[1]);
41	      if (obj && typeof obj === 'object') {
42	        profileUpdate = {
43	          level: typeof obj.level === 'string' ? obj.level : undefined,
44	          weakPoints: Array.isArray(obj.weakPoints) ? obj.weakPoints.filter((w: unknown) => typeof w === 'string') : undefined,
45	        };
46	      }
47	    } catch { /* 损坏标记：按剥离处理 */ }
48	  }
49	
50	  if (/<lesson-advance\s*\/>/.test(clean)) {
51	    clean = clean.replace(/<lesson-advance\s*\/>/g, '');
52	    lessonAdvance = true;
53	  }
54	
55	  const wrongM = /<wrong-book>([\s\S]*?)<\/wrong-book>/.exec(clean);
56	  if (wrongM) {
57	    clean = clean.replace(wrongM[0], '');
58	    try {
59	      const obj = JSON.parse(wrongM[1]);
60	      if (obj && typeof obj === 'object') {
61	        wrong = {
62	          lesson: typeof obj.lesson === 'string' ? obj.lesson : '',
63	          section: typeof obj.section === 'string' ? obj.section : '',
64	          question: typeof obj.question === 'string' ? obj.question : '',
65	        };
66	      }
67	    } catch { /* 损坏标记：按剥离处理 */ }
68	  }
69	
70	  for (const m of clean.matchAll(/<test-input>([\s\S]*?)<\/test-input>/g)) {
71	    const t = m[1];
72	    testInputs.push(t.startsWith('\n') ? t.slice(1) : t);
73	  }
74	  for (const m of clean.matchAll(/<expected-output>([\s\S]*?)<\/expected-output>/g)) {
75	    const t = m[1];
76	    expectedOutputs.push(t.startsWith('\n') ? t.slice(1) : t);
77	  }
78	  clean = clean.replace(/<test-input>[\s\S]*?<\/test-input>/g, '').replace(/<expected-output>[\s\S]*?<\/expected-output>/g, '').trim();
79	
80	  const runFileM = /<run-file>([^<]+)<\/run-file>/.exec(clean);
81	  if (runFileM) {
82	    clean = clean.replace(runFileM[0], '');
83	    wrong_run_file = runFileM[1].trim();
84	  }
85	
86	  // 当前任务目标：<current-task>文字</current-task>；<task-cancel/> 清除任务
87	  if (/<task-cancel\s*\/>/.test(clean)) {
88	    clean = clean.replace(/<task-cancel\s*\/>/g, '');
89	    currentTask = '';
90	  }
91	  const taskM = /<current-task>([^<]*)<\/current-task>/.exec(clean);
92	  if (taskM) {
93	    clean = clean.replace(taskM[0], '');
94	    currentTask = taskM[1].trim();
95	  }
96	
97	  return { clean: clean.trim(), profileUpdate, lessonAdvance, wrong, testInputs, expectedOutputs, runFile: wrong_run_file, currentTask };
98	}
