100	/** 把学生档案与当前进度注入 system 提示词（AI 据此个性化教学） */
101	export function buildProfileContext(
102	  profile: { level: string; weakPoints: string[]; summary?: string },
103	  lesson?: { lessonTitle: string; sectionTitle: string },
104	): string {
105	  const parts: string[] = [];
106	  if (profile.level !== 'unknown') parts.push(`学生水平：${profile.level}`);
107	  if (profile.weakPoints.length > 0) parts.push(`薄弱点：${profile.weakPoints.join('、')}`);
108	  if (profile.summary) parts.push(`上一段学习摘要：${profile.summary}`);
109	  if (lesson) parts.push(`当前学习进度：第「${lesson.lessonTitle}」关 · 第「${lesson.sectionTitle}」节`);
110	  return parts.length > 0 ? `\n【学生档案】${parts.join('；')}。` : '';
111	}
