636	  // ===== AI 文件动作（M2-5：createFile——AI 回复的 ```file:路径 围栏自动/手动写入工作区）=====
637	
638	  /**
639	   * 编译运行工作区文件（M2-6）：结果以 notice 展示，并作为隐式轮注入 history——
640	   * 让 AI「看到」程序的编译输出与运行输出，下一条回复即可分析调试。
641	   * 需要输入的程序由超时兜底并提示（完整判题输入属 M5）。
642	   */
643	  private async runFileAction(relPath: string): Promise<void> {
644	    if (!this.runner) {
645	      this.pushNotice('运行功能未就绪喵');
646	      return;
647	    }
648	    const root = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
649	    if (!root) {
650	      this.pushNotice('请先打开一个工作区文件夹（文件 → 打开文件夹）再运行喵');
651	      return;
652	    }
653	    const abs = path.resolve(root, relPath);
654	    if (!abs.startsWith(root + path.sep) || !abs.endsWith('.cpp')) {
655	      this.pushNotice(`只能运行工作区内的 .cpp 文件喵（收到：${relPath}）`);
656	      return;
657	    }
658	    this.post({ type: 'busy', busy: true });
659	    const testPoints = this.pendingTestInputs.get(relPath) ?? [];
660	    const expectedList = this.pendingExpected.get(relPath) ?? [];
661	    this.pushNotice(`正在编译运行 ${relPath} …${testPoints.length > 0 ? `（${testPoints.length} 组测试点，自动比对期望输出）` : '（10 秒超时保护）'}`);
662	    try {
663	      // 多测试点循环判题（竞赛正确性）：无预置输入时跑一组 EOF；逐点收集实际输出，
664	      // 有期望输出时按「trim 后逐行比对」自动判定——不依赖 AI 印象
665	      const points: { input: string; output: string; pass: boolean | null; expected?: string; timedOut: boolean; code: number | null }[] = [];
666	      let compileOutput = '';
667	      const inputs = testPoints.length > 0 ? testPoints : [undefined];
668	      for (let i = 0; i < inputs.length; i++) {
669	        const stdin = inputs[i];
670	        const r = await this.runner.runCpp(abs, stdin);
671	        compileOutput = r.compileOutput;
672	        if (r.compileOutput && !r.ok && r.exitCode === null) {
673	          points.push({ input: stdin ?? '', output: r.compileOutput, pass: false, timedOut: false, code: null });
674	          break; // 编译失败：无测试点意义，直接结束
675	        }
676	        const exp = expectedList[i];
677	        const actualNorm = r.runOutput.replace(/\r\n/g, '\n').trim();
678	        const pass = exp !== undefined ? actualNorm === exp.replace(/\r\n/g, '\n').trim() : (r.ok && !r.timedOut);
679	        points.push({ input: stdin ?? '', output: r.runOutput, pass, expected: exp, timedOut: r.timedOut, code: r.exitCode });
680	      }
681	      const passed = points.filter(p => p.pass === true).length;
682	      const judged = expectedList.length > 0;
683	      const summary = [
684	        compileOutput ? `【编译输出】\n${compileOutput}` : '',
685	        ...points.map((p, i) => {
686	          const tag = testPoints.length > 0
687	            ? `测试点 ${i + 1}/${points.length}：${p.timedOut ? '超时' : p.pass === true ? '通过 ✓' : p.pass === false ? '未通过 ✗' : `退出码 ${p.code ?? '?'}`}`
688	            : '运行结果';
689	          const expPart = p.expected !== undefined ? `期望输出：\n${p.expected}\n` : '';
690	          return `【${tag}】\n输入：${p.input || '（无）'}\n${expPart}实际输出：\n${p.output}`;
691	        }),
692	        judged ? `【自动判定】通过率 ${passed}/${points.length}${passed === points.length ? ' —— 全部通过！' : ''}` : '',
693	      ].filter(Boolean).join('\n\n');
694	      this.pushNotice(summary || '运行完成，无输出');
695	      // 隐式轮注入：AI「看到」逐测试点的客观对比结果——基于数据精准分析，不再凭印象判定
696	      const allPass = judged && passed === points.length;
697	      const kind = allPass ? 'save' : 'error';
698	      const brief = summary.length > 2500 ? summary.slice(0, 2500) + '\n…（已截断）' : summary;
699	      const elapsed = this.mockStartedAt ? `（模拟练习已用时 ${Math.round((Date.now() - this.mockStartedAt) / 60000)} 分钟）` : '';
700	      const judgeHint = judged
701	        ? `以下是随堂练习多组测试点的「期望 vs 实际」自动比对结果——请基于客观数据分析：全对时祝贺并输出 <lesson-advance/>；未全对时针对第一个 ✗ 的测试点，解释期望与实际的差异原因并给方向提示（不给完整代码）。`
702	        : '请根据输出简短判断程序是否正确、指出问题与方向，1~3 句。';
703	      await this.runCompanion(kind, `（系统提示：用户刚编译运行了 ${relPath}。）${elapsed}\n${judgeHint}\n${brief}`);
704	    } catch (e) {
705	      const msg = (e as Error).message || '';
706	      if (/ENOENT|spawn/i.test(msg)) {
707	        this.pushNotice('没有找到 g++ 编译器喵。请安装 MinGW-w64 或 w64devkit，并在设置里把 cspCat.gppPath 指向 g++ 所在路径后重试');
708	      } else {
709	        this.pushNotice(`运行失败：${msg}`);
710	      }
711	    } finally {
712	      this.post({ type: 'busy', busy: false });
713	    }
714	  }
