716	  /**
717	   * 在工作区内创建文件（目录不存在自动创建）并打开。安全约束：
718	   * 路径必须是相对路径且解析后落在工作区根内（防 .. 与盘符逃逸）；文件已存在时弹确认防误覆盖。
719	   */
720	  private async createFileAction(relPath: string, content: string): Promise<void> {
721	    const root = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
722	    if (!root) {
723	      this.pushNotice('请先打开一个工作区文件夹（文件 → 打开文件夹），AI 才能帮你创建文件喵');
724	      return;
725	    }
726	    const abs = path.resolve(root, relPath);
727	    if (!abs.startsWith(root + path.sep)) {
728	      this.pushNotice(`路径 ${relPath} 不在工作区内，已拒绝创建喵`);
729	      return;
730	    }
731	    try {
732	      await vscode.workspace.fs.stat(vscode.Uri.file(abs));
733	      const pick = await vscode.window.showWarningMessage(
734	        `文件 ${relPath} 已存在，要覆盖吗喵？`, { modal: true }, '覆盖',
735	      );
736	      if (pick !== '覆盖') return;
737	    } catch { /* 不存在：正常创建路径 */ }
738	    try {
739	      await vscode.workspace.fs.createDirectory(vscode.Uri.file(path.dirname(abs)));
740	      await vscode.workspace.fs.writeFile(vscode.Uri.file(abs), Buffer.from(content, 'utf8'));
741	      await vscode.window.showTextDocument(vscode.Uri.file(abs));
742	      this.pushNotice(`✅ 已创建 ${relPath} 并打开，动手试试吧喵`);
743	    } catch (e) {
744	      this.pushNotice(`创建 ${relPath} 失败：${(e as Error).message}`);
745	    }
746	  }
