790	  /** 解析 AI 回复中的 ```file:路径 围栏并自动创建文件（done 后调用，无需用户逐个点击）。
791	   * testInputs：随堂练习的测试输入，按围栏出现顺序绑定（运行时喂 stdin） */
792	  private autoCreateFiles(full: string, testInputs: string[] = [], expectedOutputs: string[] = []): void {
793	    let i = 0;
794	    for (const match of full.matchAll(/```file:([^\n`]+)\n([\s\S]*?)```/g)) {
795	      const rel = match[1].trim();
796	      void this.createFileAction(rel, match[2].replace(/\n$/, ''));
797	      if (i === 0) {
798	        if (testInputs.length > 0) this.pendingTestInputs.set(rel, testInputs); // 全部测试点绑定到首个 file: 围栏
799	        if (expectedOutputs.length > 0) this.pendingExpected.set(rel, expectedOutputs);
800	      }
801	      i++;
802	    }
803	  }
